<script setup>
import { computed, onMounted, ref } from 'vue';
const props=defineProps({record:Object});
const emit=defineEmits(['close']);
const panel=ref(null);
const doc=computed(()=>props.record.document);
const number=v=>typeof v==='number'?v.toLocaleString('zh-CN',{maximumFractionDigits:4}):v;
const time=v=>v?new Date(/[zZ]|[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'—';
let trigger;
onMounted(()=>{trigger=document.activeElement;panel.value?.focus();});
function close(){emit('close');trigger?.focus();}
function key(event){if(event.key==='Escape')close();if(event.key==='Tab'){const nodes=[...panel.value.querySelectorAll('button,a,input,select,textarea')];const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===panel.value)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}}
</script>
<template>
<Teleport to="body"><div class="business-record-mask" @click.self="close"><section ref="panel" class="business-record-dialog" role="dialog" aria-modal="true" aria-labelledby="business-record-title" tabindex="-1" @keydown="key"><header><div><small>执行记录详情</small><h2 id="business-record-title">{{ record.operation_title || record.title }}</h2><p>{{ record.subtitle || doc?.name || '关联单据' }}</p></div><button type="button" aria-label="关闭详情" @click="close">×</button></header><main><section class="record-event"><div><small>当次操作结果</small><strong :class="{returned:record.result==='退回'}">{{ record.result }}</strong></div><div><small>操作人</small><b>{{ record.operator_name || '未记录' }}</b></div><div><small>操作时间</small><b>{{ time(record.at) }}</b></div></section><template v-if="doc"><div class="document-heading"><h3>关联单据当前信息</h3><span>{{ doc.state }}</span></div><p class="record-note">以下显示单据当前信息；当次操作结果和时间以上方记录为准。</p><div v-if="doc.stats.length" class="record-stats"><div v-for="stat in doc.stats" :key="stat.label"><small>{{ stat.label }}</small><strong>{{ stat.unit }} {{ number(stat.value) }}</strong></div></div><dl class="record-metadata"><div v-for="field in doc.metadata" :key="field.label"><dt>{{ field.label }}</dt><dd>{{ field.label.includes('时间')||field.label==='预计到货'?time(field.value):field.value }}</dd></div></dl><section v-if="doc.lines.length"><div class="document-heading"><h3>物料明细</h3><small>{{ doc.lines.length }} 项</small></div><article v-for="(line,index) in doc.lines" :key="index" class="record-line"><div class="record-line-name"><span>{{ index+1 }}</span><strong>{{ line.name }}</strong><small v-if="line.lot">批次 {{ line.lot }}</small></div><dl class="line-values"><div v-for="value in line.values" :key="value.label" :class="{difference:value.label==='差异'&&value.value!==0}"><dt>{{ value.label }}</dt><dd>{{ number(value.value) }} <small>{{ value.unit }}</small></dd></div></dl><div v-for="(allocation,i) in line.allocations" :key="i" class="record-allocation"><p>批次 {{ allocation.lot || '—' }} · {{ allocation.location }}</p><dl class="line-values"><div v-for="value in allocation.values" :key="value.label"><dt>{{ value.label }}</dt><dd>{{ number(value.value) }} {{ value.unit }}</dd></div></dl></div></article></section><section v-if="doc.approvals.length"><div class="document-heading"><h3>审批流程与意见</h3></div><article v-for="(step,index) in doc.approvals" :key="index" class="record-approval"><div><strong>{{ step.role }}</strong><span>{{ step.state }}</span></div><small>{{ step.by || '待处理' }} · {{ time(step.at) }}</small><p v-if="step.comment">{{ step.comment }}</p></article></section></template><p v-else class="record-note">关联单据已删除或当前账号无权查看，保留当次操作记录。</p></main><footer><button class="btn btn-secondary" type="button" @click="close">关闭详情</button></footer></section></div></Teleport>
</template>
<style scoped>
.business-record-mask{position:fixed;inset:0;z-index:2200;display:flex;align-items:center;justify-content:center;background:#000a;padding:20px}.business-record-dialog{width:min(900px,100%);max-height:90vh;display:flex;flex-direction:column;background:#25251f;color:var(--text-primary);border:1px solid var(--border-default);border-radius:14px;box-shadow:0 20px 70px #0008;outline:none}.business-record-dialog header{display:flex;justify-content:space-between;gap:20px;padding:24px 28px;border-bottom:1px solid var(--border-default)}header small{color:#abc9a2}h2{font-size:22px;margin:8px 0}header p{font-size:13px;color:var(--text-muted);margin:0}header button{align-self:flex-start;background:none;border:0;color:var(--text-muted);font-size:28px;cursor:pointer}main{padding:24px 28px;overflow:auto}.record-event{display:grid;grid-template-columns:1fr 1fr 1.5fr;gap:20px;padding:18px;background:#abc9a209;border:1px solid #abc9a240;border-radius:10px}.record-event small,.record-stats small{display:block;color:var(--text-muted);font-size:12px;margin-bottom:8px}.record-event strong{font-size:24px;color:#b8d7ab}.record-event strong.returned{color:#e9a58b}.record-event b{font-size:14px;font-weight:500}.document-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0 12px}.document-heading h3{font-size:15px;margin:0}.document-heading span{font-size:12px;color:#e0bc70;background:#d4a85314;padding:4px 9px;border-radius:5px}.record-note{font-size:12px;color:var(--text-muted);line-height:1.8}.record-stats{display:flex;gap:28px;flex-wrap:wrap;padding:18px;background:#d4a85309;border-radius:8px}.record-stats strong{font-size:22px;color:#e0bc70}.record-metadata{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 24px;margin:20px 0}.record-metadata>div{display:flex;gap:16px;justify-content:space-between;font-size:13px}.record-metadata dt,.line-values dt{color:var(--text-muted);flex-shrink:0}.record-metadata dd{margin:0;text-align:right;overflow-wrap:anywhere}.record-line{border:1px solid var(--border-default);border-radius:9px;padding:16px;margin-bottom:12px}.record-line-name{display:flex;align-items:center;gap:12px;font-size:14px}.record-line-name>span{color:#e0bc70}.record-line-name small{color:var(--text-muted)}.line-values{display:flex;flex-wrap:wrap;gap:14px 26px;margin:16px 0 0}.line-values dt{font-size:11px;margin-bottom:5px}.line-values dd{font-size:15px;margin:0;font-variant-numeric:tabular-nums}.line-values small{color:var(--text-muted);font-size:11px}.line-values .difference dd{color:#f0ae81}.record-allocation{border-top:1px solid var(--border-default);margin-top:14px;padding-top:10px}.record-allocation p{font-size:12px;color:var(--text-muted)}.record-approval{border-left:2px solid #d4a85360;padding:10px 16px;margin-bottom:12px}.record-approval>div{display:flex;justify-content:space-between;font-size:13px}.record-approval span{color:#b8d7ab}.record-approval small{display:block;color:var(--text-muted);margin-top:7px}.record-approval p{font-size:13px;line-height:1.7}footer{padding:16px 28px;text-align:right;border-top:1px solid var(--border-default)}@media(max-width:600px){.business-record-mask{padding:10px}.business-record-dialog header,main{padding:18px}.record-event{grid-template-columns:1fr;gap:14px}.record-metadata{grid-template-columns:1fr}.record-event strong{font-size:21px}}
